"""Durable research artifacts, scoped feature cards, generated failures and real3D binding."""
import sys,json,sqlite3
from pathlib import Path
import numpy as np
sys.path.insert(0,str(Path(__file__).parent))
import mlp_fidelity_v2_plan as P
from mlp_atlas_publish_final import Archive
from shared.dist_protocol.mechanism_trace import file_sha,digest

def main():
    plan=P.read(P.OUT/'plan.json');A=Archive(P.PUBLIC,P.RUN,plan);refs={};sem=P.read(P.OUT/'semantics-result-v2.json');fresh=P.read(P.OUT/'fresh-evaluation-result.json');trained=P.read(P.OUT/'trained-result.json');tails={}
    for key,path in [('plan',P.OUT/'plan.json'),('controlled_prereg',P.PUBLIC/'controlled-v4-prereg.research.json'),('development',P.OUT/'development-result.json'),('extension',P.OUT/'selection-extension.json'),('fresh_evaluation',P.OUT/'fresh-evaluation-result.json'),('semantics',P.OUT/'semantics-result-v2.json'),('v2_failed_pilot',P.OUT/'pilot-result.json'),('v3_failed_pilot',P.OUT/'pilot-v3-result.json'),('v4_pilot',P.OUT/'pilot-v4-result.json'),('layout_diagnostic',P.OUT/'tail-layout-diagnostic.json')]:refs[key]=A.put(key,P.read(path))
    for part in ['natural','generated','capability']:
        folder=P.OUT/{'natural':'tail-natural','generated':'tail-generated-v2','capability':'tail-capability-v3'}[part];p=folder/'result.json'
        if not p.exists():continue
        doc=P.read(p);tref=A.put('tail-'+part,doc);refs['tail_'+part]=tref;tails[part]={k:v for k,v in doc.items() if k not in ['rows','native_files']};tails[part]['n_rows']=len(doc.get('rows',[]));tails[part]['artifact_sha256']=tref
        if doc.get('native_files'):refs['native_tail_'+part]=A.put('native-tail-'+part,{'schema':'research_native_tensor_index.v1','files':[A.native(folder/r['path'],r['sha256']) for r in doc['native_files']]})
    layerrefs={}
    for b in range(36):
        tr=trained['layers'][b];fp=P.read(P.OUT/f'fresh-evaluation/B{b:02d}-result.json');states=A.native(P.ROOT/tr['state_path'],tr['state_sha256']);stats=A.native(P.OUT/f'fresh-evaluation/B{b:02d}-statistics.npz',fp['statistics_sha256']);layerrefs[str(b)]=A.put(f'dictionary-B{b:02d}',{'schema':'mlp_fidelity_layer.v2','block':b,'dictionary':states,'fresh_statistics':stats,'training':tr,'fresh_evaluation':fp})
    refs['dictionary_layers']=layerrefs
    for name in ['controlled-bank','natural-bank']:
        man=P.read(P.OUT/name/'manifest.json');assert man['state']=='complete';refs[name]=A.put(name,{'schema':'research_native_tensor_index.v1','manifest':man,'files':[A.native(P.OUT/name/r['path'],r['sha256']) for r in man['files']]})
    case_refs=[];db=sqlite3.connect(P.OUT/'controlled-bank/samples.sqlite3');cursor=db.execute('SELECT idx,body FROM samples ORDER BY idx')
    while True:
        rows=cursor.fetchmany(64)
        if not rows:break
        case_refs.append(A.put('cases-'+str(rows[0][0]),{'schema':'mlp_fidelity_cases.v4','first_index':rows[0][0],'cases':[json.loads(s) for i,s in rows]}))
    db.close();refs['case_index']=A.put('case-index',{'schema':'mlp_fidelity_case_index.v1','n':4096,'chunks':case_refs})
    sources=P.read(P.OUT/'fresh-documents.json')
    for name in ['natural','controlled']:
        chunks=[A.put(f'sources-{name}-{i}',{'schema':'research_source_documents.v1','dataset':name,'documents':sources[name][i:i+64]}) for i in range(0,len(sources[name]),64)];refs['source_'+name]=A.put('source-index-'+name,{'schema':'research_source_index.v1','dataset':name,'chunks':chunks,'documents_sha256':file_sha(P.OUT/'fresh-documents.json')})
    semantics_refs={};cards=[];edges=[]
    for row in sem['layers']:
        b=row['block'];folder=P.OUT/'semantics-v2';art=A.put(f'semantics-B{b:02d}',{**row,'schema':'mlp_fidelity_semantics_layer.v2','latent':A.native(folder/f'B{b:02d}-latent.npy',row['latent_sha256']),'statistics':A.native(folder/f'B{b:02d}-statistics.npz',row['statistics_sha256']),'full_native_correlation':A.native(folder/f'B{b:02d}-native-feature-correlation.npz',row['native_correlation_sha256'])});semantics_refs[str(b)]=art
        for f in row['features']:
            fid=f'{A.snap}:B{b}:mlp.output:SAE4096k256:F{f["feature"]}:{P.RUN}';level='heldout' if f['functional_eligible'] else 'observation';cards.append({'id':fid,'layer':b,'boundary':'mlp.output_sae','index':{'space':'dictionary','feature':f['feature'],'dictionary_size':4096,'dictionary_version':P.RUN},'method':'unlabelled outputSAE; discoveryonlynomination; freshgeneratedattributeconditionalresponses','run_id':P.RUN,'label':f'B{b}/F{f["feature"]} · {f["nomination_factor"]}回答响应候选','evidence':{'level':level,'artifact_sha256':art},'counterexamples':[f['response_counterexample'],{'reason':'semanticmonosemanticity andnaturalcontextprediction unestablished; poorfidelityblocks upgrade','fidelity_gate':row['fidelity_gate']}],'scope':{'functional_eligible':f['functional_eligible'],'readout_roles':['selected_record_end','assistant_boundary'],'replicated_by_readout':f['replicated_by_readout'],'dictionary_sha256':trained['layers'][b]['state_sha256'],'native_feature_mapping':'correlation only; not native U index'}});edges.append({'id':digest({'feature':fid,'mapping':'conditionalanswer'}),'source':'language:document_'+f['nomination_factor']+'_answer','target':fid,'relation':'heldout_conditional_response' if f['functional_eligible'] else 'observed_conditional_response','run_id':P.RUN,'evidence':{'level':level,'artifact_sha256':art},'scope':'English taskinstructions withEnglish/Chinesebackgrounds; notgeneral crosslanguageorworldknowledge mechanism'})
    refs['semantic_layers']=semantics_refs
    if 'generated' in tails:
        generated=tails['generated'];summary=generated.get('summary',{});proof=refs['tail_generated'];group=next(r for r in sem['layers'] if r['block']==35)['selected_group'];gid=f'{A.snap}:B35:SAEgroup:{digest(group)[:12]}:{P.RUN}';outid=f'{A.snap}:B35:finalnorm-unembedding:{P.RUN}';rid=f'{A.snap}:B35:incoming-residual:{P.RUN}';supported=bool(summary.get('effect_supported'))
        cards +=[{'id':gid,'layer':35,'boundary':'mlp.output_sae_group','index':{'space':'dictionary','features':group,'dictionary_version':P.RUN},'method':'discoveryselected16featurejointremoval alpha0,.5,1; sameRMSrandomgroup; actual8token generation','run_id':P.RUN,'label':'B35联合特征移除 · '+('支持范围效应' if supported else '未支持预注册生成效应'),'evidence':{'level':'intervention' if supported else 'negative','artifact_sha256':proof},'counterexamples':[{'reason':'jointoperation doesnotidentify individualnecessity; latergenerationunmodified','selected_loss':summary.get('selected_loss'),'random_comparison':summary.get('target_minus_random_loss')}],'scope':{'native_parameters_edited':0,'min_edit_params':None,'intervention_kind':'activation_feature_group','group_size':len(group),'single_query_position_only':True}},
          {'id':rid,'layer':35,'boundary':'pre_mlp_residual','index':{'space':'residual','field':'all2560preMLPcoordinates'},'method':'originalincomingresidual retained whenqueryMLPoutputzeroed; originalnativeprefixKV andlatergeneration retained','run_id':P.RUN,'label':'B35查询位置MLP置零后的残差读出','evidence':{'level':'intervention','artifact_sha256':proof},'counterexamples':[{'reason':'doesnotshowwholeMLP/otherlayers dispensable; task accuracycanbesaturated'}],'scope':{'condition':next((r for r in summary.get('dose_curve',[]) if r['condition']=='zero'),None)}},
          {'id':outid,'layer':35,'boundary':'final_norm_unembedding','index':{'space':'residual','field':'all2560finalcoordinates'},'method':'nativefullsequenceRMSNorm/headlayout preserved; trueHookandall36prefixKVbitwiseverification','run_id':P.RUN,'label':'B35→最终RMSNorm→真实输出层','evidence':{'level':'parameter_source','artifact_sha256':proof},'counterexamples':[{'reason':'tailshortcut notvalidforearlierlayers; notgraph-only reconstruction'}]}]
        edges +=[{'id':digest({'group':gid,'output':outid}),'source':gid,'target':outid,'relation':'joint_ablation_effect' if supported else 'joint_ablation_not_supported','run_id':P.RUN,'evidence':{'level':'intervention' if supported else 'negative','artifact_sha256':proof}}, {'id':digest({'residual':rid,'output':outid}),'source':rid,'target':outid,'relation':'actual_tail_path_with_query_MLP_zero','run_id':P.RUN,'evidence':{'level':'intervention','artifact_sha256':proof}}]
    names=[p for p in Path(__file__).parent.glob('mlp_fidelity_v2*.py') if p.name!='test_mlp_fidelity_v2.py'];refs['source_code']=A.sources([str(p.relative_to(P.ROOT)) for p in names])
    complete=len(tails)==3;v=np.array([r['results']['lockbox']['FVU']['dictionary'] for r in fresh['layers']]);target=tails.get('generated',{}).get('summary',{});cap=tails.get('capability',{}).get('summary',{}).get('NI',{});ni=cap.get('selected_1',{}).get('status','not_tested')
    recovery=tails.get('natural',{}).get('summary',{}).get('operations',{}).get('sae_full',{}).get('loss_recovered')
    conclusion=f'新字典lockbox FVU中位{np.median(v):.4f}，仅B35通过两组保真门（FVU {v[35]:.4f}）；4096条自然属性生成全部行为格'+('通过。' if sem['behavior_gate'] else '未全部通过。')+(f'自然损失恢复{recovery:.3f}，低于同预算原生对照；压缩指标改善不等于行为保真。' if recovery is not None else '')+('联合特征干预效应达到预注册阈值。' if target.get('effect_supported') else '联合特征干预未支持预注册效应。')+f'所选操作能力保持：{ni}。'
    report={'schema':'mlp_fidelity_report.v2','state':'complete' if complete else 'running','bank_available':True,'conclusion':conclusion,'plan':plan,'controlled_prereg':P.read(P.PUBLIC/'controlled-v4-prereg.research.json'),'development':P.read(P.OUT/'development-result.json'),'extension':P.read(P.OUT/'selection-extension.json'),'selection':P.read(P.OUT/'selection-extension.json'),'fresh_evaluation':fresh,'semantics':sem,'tails':tails,'artifact_refs':refs,
       'limitations':['SAE seesnativeMLPoutput; lowerFVU isnotinput-to-output predictionorfullmechanism extraction.','OnlyB35passed freshfidelity; rawmidlayerresponses retainedwithoutsemanticpromotion.','Conditionedanswerfeatures canreflectanswerpreparation; prequestionreplication separatelyrecorded.','Joint16featureintervention doesnotidentify individuallynecessaryfeatures.','OnlylastMLPtail shortcut validated; fullgraph-only prediction andallneuronsemanticdecoding incomplete.','Capabilitypool previouslyexposed; noninferiority scopedtotheactualoperation andkeyedmonitor.','Fullmodelparameters unchanged; rawtensorfiles node-local CAS, no fakeofflinefields.']}
    rr=A.put('report',report);gr=A.put('graph',{'schema':'research_graph.v1','feature_cards':cards,'graph_edges':edges,'semantic_mechanisms_closed':0,'note':'48scopedfeaturecards, not48uniquely decodednative neurons.'})
