    P.save(P.OUT/('registration-final.json' if complete else 'registration-progress.json'),{'run_id':P.RUN,'model_snapshot':A.snap,'provenance':A.prov,'report_sha256':rr,'graph_sha256':gr,'artifact_refs':refs,'state':report['state']},False)
