    oldreg=P.read(P.OLD/'interpretation-registration-v2.json');oldA=Archive(P.ROOT/'research/mlp_atlas/dictionary_v1',oldreg['run_id'],oldreg);old=oldA.lib.artifact(oldreg['report_sha256']);old['corrected_split_note']='v1的confirm实际上全部为英文Wikipedia，lockbox全部为中文Wikipedia；不是两个语言配平的重复留出。旧数值不变，不能把二者误差差异只归于普通推广。新版使用配平的新材料。';orpt=oldA.put('split-interpretation-correction',old);oldA.bind(orpt,oldreg['graph_sha256'],{'study_type':'mlp_dictionary_atlas','native_bank':True,'layer_refs':oldreg['layer_refs']},'全36层旧自然字典 · 语言切分解释已纠正',{'dictionary':{'status':'done','raw_numbers_unchanged':True},'correction':{'status':'done','new_run':P.RUN},'semantic_causal_closure':{'status':'not_complete'}})
    print({'report':rr,'graph':gr,'state':report['state'],'capability':cap},flush=True)
